# Compute max all-same rectangles for test grid

def max_rects(mat):
    R,C=len(mat),len(mat[0]); out=[]
    for color in sorted({v for row in mat for v in row}):
        heights=[0]*C; best=[]
        # For each r, histogram consecutive up to row r same color
        for r in range(R):
            heights=[heights[c]+1 if mat[r][c]==color else 0 for c in range(C)]
            for l in range(C):
                mn=R+1
                for rr in range(l,C):
                    mn=min(mn, heights[rr])
                    if mn:
                        area=mn*(rr-l+1)
                        if area>=20: best.append((area,r-mn+1,l,r,rr,mn,rr-l+1))
        out.extend((color,)+x for x in sorted(best,reverse=True)[:10])
    return out
